def _from_compressed(cls: t.Type[T], path: str, input_format: str) -> T:
    if input_format in ["gz", "xz", "bz2", "tar", cls._export_ext()]:
        from fs.tarfs import ReadTarFS

        compression = input_format
        if compression == "tar":
            compression = None
        if compression == cls._export_ext():
            compression = "xz"
        ret_fs = ReadTarFS(path)
    elif input_format == "zip":
        from fs.zipfs import ReadZipFS

        ret_fs = ReadZipFS(path)
    elif input_format == "folder":
        ret_fs: FS = open_fs(path)
    else:
        raise ValueError(f"Unsupported format {input_format}")

    return cls.from_fs(ret_fs)

def data(self):
    if not self._flag_full:
        return self._data[: self._cur]
    return self._data

def __len__(self):
    if not self._flag_full:
        return self._cur
    return self._size

def __getitem__(self, sl: slice):
    if not self._flag_full:
        return self._data[: self._cur][sl]
    return (self._data[self._cur :] + self._data[: self._cur])[sl]

def pytest_runtest_setup(item: Item) -> None:
    config = item.config
    if "requires_gpus" in item.keywords and not config.getoption(_RUN_GPU_TESTS_MARKER):
        item.add_marker(
            pytest.mark.skip(
                reason=f"need {_RUN_GPU_TESTS_MARKER} option to run gpus related tests."
            )
        )
    # We don't run gRPC tests on Windows
    if "requires_grpc" in item.keywords and not config.getoption(
        _RUN_GRPC_TESTS_MARKER
    ):
        item.add_marker(
            pytest.mark.skip(
                reason=f"need {_RUN_GRPC_TESTS_MARKER} option to run grpc related tests."
            )
        )

def exit_cloudpickle_context(cls, imported_modules: list[ModuleType]) -> None:
    """
    Exit the context for cloudpickle, unregister imported external modules.

    Needs to be called after self.flush
    """
    if not imported_modules:
        return

    for mod in imported_modules:
        cloudpickle.unregister_pickle_by_value(mod)

