def __getattr__(self, item: t.Any) -> t.Any:
    if item in self.__slots__:
        raise AttributeError(f"Attribute {item} is private to {self}.")
    if self._proxy is None:
        self._proxy = self._load_proxy()
    assert self._initialized and self._proxy is not None
    return getattr(self._proxy, item)

def get_class(self, import_module: bool = True) -> t.Type[T]:
    if self._runtime_class is None:
        try:
            m = sys.modules[self.module]
        except KeyError:
            if import_module:
                import importlib

                m = importlib.import_module(self.module)
            else:
                raise ValueError(f"Module {self.module} not imported")

        self._runtime_class = t.cast("t.Type[T]", getattr(m, self.qualname))

    return self._runtime_class

