async def api_func(request: Request) -> Response:
    # handle_request may raise 4xx or 5xx exception.
    output = None
    with self.bento_service.context.in_request(request) as ctx:
        try:
            input_data = await api.input.from_http_request(request)
            if api.multi_input:
                if api.needs_ctx:
                    input_data[api.ctx_param] = ctx
                if is_async_callable(api.func):
                    output = await api.func(**input_data)
                else:
                    output = await run_in_threadpool(api.func, **input_data)
            else:
                args = (input_data,)
                if api.needs_ctx:
                    args = (input_data, ctx)
                if is_async_callable(api.func):
                    output = await api.func(*args)
                else:
                    output = await run_in_threadpool(api.func, *args)

            response = await api.output.to_http_response(
                output, ctx if api.needs_ctx else None
            )

        except BentoMLException as e:
            log_exception(request, sys.exc_info())
            if output is not None:
                import inspect

                signature = inspect.signature(api.output.to_proto)
                param = next(iter(signature.parameters.values()))
                ann = ""
                if param is not inspect.Parameter.empty:
                    ann = param.annotation

                # more descriptive errors if output is available
                logger.error(
                    "Function '%s' has 'input=%s,output=%s' as IO descriptor, and returns 'result=%s', while expected return type is '%s'",
                    api.name,
                    api.input,
                    api.output,
                    type(output),
                    ann,
                )

            status = e.error_code.value
            if 400 <= status < 500 and status not in (401, 403):
                response = JSONResponse(
                    content="BentoService error handling API request: %s"
                    % str(e),
                    status_code=status,
                )
            else:
                response = JSONResponse("", status_code=status)
        except Exception:  # pylint: disable=broad-except
            # For all unexpected error, return 500 by default. For example,
            # if users' model raises an error of division by zero.
            log_exception(request, sys.exc_info())

            response = JSONResponse(
                "An error has occurred in BentoML user code when handling this request, find the error details in server logs",
                status_code=500,
            )
        if trace_context.request_id is not None:
            response.headers["X-BentoML-Request-ID"] = str(
                trace_context.request_id
            )
        if (
            BentoMLContainer.http.response.trace_id.get()
            and trace_context.trace_id is not None
        ):
            response.headers["X-BentoML-Trace-ID"] = str(trace_context.trace_id)
        return response

async def to_http_response(self, obj: FileType, ctx: Context | None = None):
    if isinstance(obj, bytes):
        body = obj
    else:
        body = obj.read()

    if ctx is not None:
        res = Response(
            body,
            headers=ctx.response.metadata,  # type: ignore (bad starlette types)
            status_code=ctx.response.status_code,
        )
        set_cookies(res, ctx.response.cookies)
    else:
        res = Response(
            body,
            headers={
                "content-type": self._mime_type
                if self._mime_type
                else "application/octet-stream"
            },
        )
    return res

async def from_http_request(self, request: Request) -> FileLike[bytes]:
    content_type, _ = parse_options_header(request.headers["content-type"])
    if content_type.decode("utf-8") == "multipart/form-data":
        form = await request.form()
        found_mimes: t.List[str] = []
        val: t.Union[str, UploadFile]
        for val in form.values():  # type: ignore
            if isinstance(val, UploadFile):
                found_mimes.append(val.content_type)  # type: ignore (bad starlette types)
                if self._mime_type is None or val.content_type == self._mime_type:  # type: ignore (bad starlette types)
                    res = FileLike[bytes](val.file, val.filename)  # type: ignore (bad starlette types)
                    break
        else:
            if len(found_mimes) == 0:
                raise BentoMLException("no File found in multipart form")
            else:
                raise BentoMLException(
                    f"The File IO descriptor requires input to be of Content-Type '{self._mime_type}', got files with content types {', '.join(found_mimes)}"
                )
        return res  # type: ignore
    if self.mime_type is None or content_type.decode("utf-8") == self._mime_type:
        body = await request.body()
        return FileLike[bytes](io.BytesIO(body), "<request body>")
    raise BentoMLException(
        f"File should have Content-Type '{self._mime_type}' or 'multipart/form-data', got {content_type} instead"
    )

