def map(self, function: t.Callable[[T], To]) -> Params[To]:
    """
    Apply a function to all the values in the Params and return a Params of the
    return values.
    """
    args = tuple(function(a) for a in self.args)
    kwargs = {k: function(v) for k, v in self.kwargs.items()}
    return Params[To](*args, **kwargs)

def list(self, tag: t.Optional[t.Union[Tag, str]] = None) -> t.List[Item]:
    if not tag:
        return [
            ver
            for _d in sorted(self._fs.listdir("/"))
            if self._fs.isdir(_d)
            for ver in self.list(_d)
        ]

    _tag = Tag.from_taglike(tag)
    if _tag.version is None:
        if not self._fs.isdir(_tag.name):
            raise NotFound(
                f"no {self._item_type.get_typename()}s with name '{_tag.name}' found"
            )

        tags = sorted(
            [
                Tag(_tag.name, f.name)
                for f in self._fs.scandir(_tag.name)
                if f.is_dir
            ]
        )
        return [self._get_item(t) for t in tags]
    else:
        return [self._get_item(_tag)] if self._fs.isdir(_tag.path()) else []

def _get_item(self, tag: Tag) -> Item:
    """
    Creates a new instance of Item that represents the item with tag `tag`.
    """
    return self._item_type.from_fs(self._fs.opendir(tag.path()))

def _recreate_latest(self, tag: Tag):
    try:
        items = self.list(tag.name)
    except NotFound:
        raise NotFound(
            f"no {self._item_type.get_typename()}s with name '{tag.name}' exist in BentoML store {self._fs}"
        )

    if len(items) == 0:
        raise NotFound(
            f"no {self._item_type.get_typename()}s with name '{tag.name}' exist in BentoML store {self._fs}"
        )

    items.sort(reverse=True, key=lambda item: item.creation_time)
    tag.version = items[0].tag.version

    with self._fs.open(tag.latest_path(), "w") as latest_file:
        latest_file.write(tag.version)

def get(self, tag: t.Union[Tag, str]) -> Item:
    """
    store.get("my_bento")
    store.get("my_bento:v1.0.0")
    store.get(Tag("my_bento", "latest"))
    """
    _tag = Tag.from_taglike(tag)
    if _tag.version is None or _tag.version == "latest":
        try:
            _tag.version = self._fs.readtext(_tag.latest_path())

            if not self._fs.exists(_tag.path()):
                self._recreate_latest(_tag)
        except fs.errors.ResourceNotFound:
            self._recreate_latest(_tag)

    path = _tag.path()
    if self._fs.exists(path):
        return self._get_item(_tag)

    matches = self._fs.glob(f"{path}*/")
    counts = matches.count().directories
    if counts == 0:
        raise NotFound(
            f"{self._item_type.get_typename()} '{tag}' is not found in BentoML store {self._fs}, "
            "you may need to run `bentoml models pull` first"
        )
    elif counts == 1:
        match = next(iter(matches))
        return self._get_item(Tag(_tag.name, match.info.name))
    else:
        vers: t.List[str] = []
        for match in matches:
            vers += match.info.name
        raise BentoMLException(
            f"multiple versions matched by {_tag.version}: {vers}"
        )

def register(self, tag: str | Tag) -> t.Generator[str, None, None]:
    _tag = Tag.from_taglike(tag)

    item_path = _tag.path()
    if self._fs.exists(item_path):
        raise BentoMLException(
            f"Item '{_tag}' already exists in the store {self._fs}"
        )
    self._fs.makedirs(item_path)
    try:
        yield self._fs.getsyspath(item_path)
    except Exception:
        self._fs.removetree(item_path)
        raise
    # item generation is most likely successful, link latest path
    if (
        not self._fs.exists(_tag.latest_path())
        or self.get(_tag).creation_time >= self.get(_tag.name).creation_time
    ):
        with self._fs.open(_tag.latest_path(), "w") as latest_file:
            latest_file.write(_tag.version)

def delete(self, tag: t.Union[str, Tag]) -> None:
    _tag = Tag.from_taglike(tag)

    if _tag.version == "latest":
        try:
            _tag.version = self._fs.readtext(_tag.latest_path())
        except fs.errors.ResourceNotFound:
            # if latest path doesn't exist, we don't need to delete anything
            return

    if not self._fs.exists(_tag.path()):
        raise NotFound(f"{self._item_type.get_typename()} '{tag}' not found")

    self._fs.removetree(_tag.path())
    if self._fs.isdir(_tag.name):
        versions = self.list(_tag.name)
        if len(versions) == 0:
            # if we've removed all versions, remove the directory
            self._fs.removetree(_tag.name)
        else:
            new_latest = sorted(versions, key=lambda x: x.creation_time)[-1]
            # otherwise, update the latest version
            assert new_latest.tag.version is not None
            self._fs.writetext(_tag.latest_path(), new_latest.tag.version)

def from_taglike(cls, taglike: t.Union["Tag", str]) -> "Tag":
    if isinstance(taglike, Tag):
        return taglike
    return cls.from_str(taglike)

def from_str(cls, tag_str: str) -> "Tag":
    if ":" not in tag_str:
        return cls(tag_str, None)
    try:
        name, _, version = tag_str.partition(":")
        if not version:
            # in case users mistakenly define "bento:"
            raise BentoMLException(
                f"{tag_str} contains trailing ':'. Maybe you meant to use `{tag_str}:latest`?"
            )
        return cls(name, version)
    except ValueError:
        raise BentoMLException(f"Invalid {cls.__name__} {tag_str}")

def _load_raw_model(bento_model: str | Tag | bentoml.Model) -> onnx.ModelProto:
    if not isinstance(bento_model, bentoml.Model):
        bento_model = get(bento_model)

    model_path = bento_model.path_of(MODEL_FILENAME)
    raw_model = onnx.load(model_path)
    return raw_model

def __str__(self):
    if self.version is None:
        return self.name
    else:
        return f"{self.name}:{self.version}"

def guess_format(cls, path: str) -> str:
    _, ext = fs.path.splitext(path)

    if ext == "":
        return cls._export_ext()

    ext = ext[1:]
    if ext in [cls._export_ext(), "gz", "xz", "bz2", "tar", "zip"]:
        return ext
    else:
        return cls._export_ext()

def _compress(self, path: str, output_format: str):
    if output_format in ["gz", "xz", "bz2", "tar", self._export_ext()]:
        from fs.tarfs import WriteTarFS

        compression = output_format
        if compression == "tar":
            compression = None
        if compression == self._export_ext():
            compression = "xz"
        out_fs = WriteTarFS(path, compression)
    elif output_format == "zip":
        from fs.zipfs import WriteZipFS

        out_fs = WriteZipFS(path)
    elif output_format == "folder":
        out_fs: FS = open_fs(path, writeable=True, create=True)
    else:
        raise ValueError(f"Unsupported format {output_format}")

    fs.mirror.mirror(self._fs, out_fs, copy_if_newer=False)
    out_fs.close()

def isinstance(self, obj: t.Any) -> t.TypeGuard[T]:
    try:
        return isinstance(obj, self.get_class(import_module=False))
    except ValueError:
        return False

def from_arrow(self, batch: pyarrow.RecordBatch) -> ext.NpNDArray:
    df = batch.to_pandas()
    if not LazyType("pandas", "DataFrame").isinstance(df):
        raise InvalidArgument("Unable to convert input into numpy ndarray.")
    return df.to_numpy()

async def to_proto(self, obj: ImageType) -> pb.File:
    if LazyType["ext.NpNDArray"]("numpy.ndarray").isinstance(obj):
        image = PIL.Image.fromarray(obj, mode=self._pilmode)
    elif LazyType["PIL.Image.Image"]("PIL.Image.Image").isinstance(obj):
        image = obj
    else:
        raise BadInput(
            f"Unsupported Image type received: '{type(obj)}', the Image IO descriptor only supports 'np.ndarray' and 'PIL.Image'.",
        ) from None
    ret = io.BytesIO()
    image.save(ret, format=self._format)

    return pb.File(kind=self._mime_type, content=ret.getvalue())

def default(self, o: type) -> t.Any:
    if dataclasses.is_dataclass(o):
        return dataclasses.asdict(o)
    if LazyType["ext.NpNDArray"]("numpy.ndarray").isinstance(o):
        return o.tolist()
    if LazyType["ext.NpGeneric"]("numpy.generic").isinstance(o):
        return o.item()
    if LazyType["ext.PdDataFrame"]("pandas.DataFrame").isinstance(o):
        return o.to_dict()  # type: ignore
    if LazyType["ext.PdSeries"]("pandas.Series").isinstance(o):
        return o.to_dict()  # type: ignore
    if LazyType["pydantic.BaseModel"]("pydantic.BaseModel").isinstance(o):
        obj_dict = o.dict()
        if "__root__" in obj_dict:
            obj_dict = obj_dict.get("__root__")
        return obj_dict
    if attr.has(o):
        return bentoml_cattr.unstructure(o)
    return super().default(o)

def from_type(cls, typ_: t.Union[LazyType[T], t.Type[T]]) -> LazyType[T]:
    if isinstance(typ_, LazyType):
        return typ_
    return cls(typ_)

def __eq__(self, o: object) -> bool:
    """
    LazyType("numpy", "ndarray") == np.ndarray
    """
    if isinstance(o, type):
        o = self.__class__(o)

    if isinstance(o, LazyType):
        return self.module == o.module and self.qualname == o.qualname

    return False

def ensure_larger_than(target: int | float) -> t.Callable[[int | float], bool]:
    """Ensure that given value is (lower, inf]"""

    def v(value: int | float) -> bool:
        return value > target

    return v

def issubclass(self, klass: type) -> bool:
    try:
        return issubclass(klass, self.get_class(import_module=False))
    except ValueError:
        return False

def is_compatible_type(t1: AnyType, t2: AnyType) -> bool:
    """
    A very loose check that it is possible for an object to be both an instance of ``t1``
    and an instance of ``t2``.

    Note: this will resolve ``LazyType``s, so should not be used in any
    peformance-critical contexts.
    """
    if get_origin(t1) is t.Union:
        return any((is_compatible_type(t2, arg_type) for arg_type in get_args(t1)))

    if get_origin(t2) is t.Union:
        return any((is_compatible_type(t1, arg_type) for arg_type in get_args(t2)))

    if isinstance(t1, LazyType):
        t1 = t1.get_class()

    if isinstance(t2, LazyType):
        t2 = t2.get_class()

    if isinstance(t1, type) and isinstance(t2, type):
        return issubclass(t1, t2) or issubclass(t2, t1)

    # catchall return true in unsupported cases so we don't error on unsupported types
    return True

