def with_defaults(self) -> DockerOptions:
    # Convert from user provided options to actual build options with default values
    defaults: t.Dict[str, t.Any] = {}

    if self.base_image is None:
        if self.distro is None:
            defaults["distro"] = DEFAULT_CONTAINER_DISTRO
        if self.python_version is None:
            python_version = f"{version_info.major}.{version_info.minor}"
            defaults["python_version"] = python_version

    return attr.evolve(self, **defaults)

def with_defaults(self) -> CondaOptions:
    # Convert from user provided options to actual build options with default values
    defaults: dict[str, t.Any] = {}

    # When `channels` field was left empty, apply the community maintained
    # channel `conda-forge` as default
    if (
        (self.dependencies or self.pip)
        and not self.channels
        and not self.environment_yml
    ):
        defaults["channels"] = ["conda-forge"]

    return attr.evolve(self, **defaults)

def with_defaults(self) -> PythonOptions:
    # Convert from user provided options to actual build options with default values
    defaults: dict[str, t.Any] = {}

    if self.requirements_txt is None:
        if self.lock_packages is None:
            defaults["lock_packages"] = True

    return attr.evolve(self, **defaults)

async def to_proto(self, obj: FileType) -> pb.File:
    if isinstance(obj, bytes):
        body = obj
    else:
        body = obj.read()

    return pb.File(
        kind="appliction/octet-stream"
        if self._mime_type is None
        else self._mime_type,
        content=body,
    )

def validate_labels(labels: dict[str, str]):
    if not isinstance(labels, dict):
        raise ValueError("labels must be a dict!")

    for key, val in labels.items():
        if not isinstance(key, str):
            raise ValueError("label keys must be strings")

        if not isinstance(val, str):
            raise ValueError("label values must be strings")

def validate_metadata(metadata: MetadataDict):
    if not isinstance(metadata, dict):
        raise ValueError("metadata must be a dict!")

    for key, val in metadata.items():
        if not isinstance(key, (str, int, float)):
            raise ValueError("metadata keys must be strings")

        metadata[key] = _validate_metadata_entry(val)

def _validate_metadata_entry(entry: MetadataType) -> MetadataType:
    if isinstance(entry, dict):
        validate_metadata(entry)
    elif isinstance(entry, list):
        for i, val in enumerate(entry):
            entry[i] = _validate_metadata_entry(val)
    elif isinstance(entry, tuple):
        entry = tuple((_validate_metadata_entry(x) for x in entry))

    elif LazyType("numpy", "ndarray").isinstance(entry):
        entry = entry.tolist()  # type: ignore (LazyType)
        _validate_metadata_entry(entry)
    elif LazyType("numpy", "generic").isinstance(entry):
        entry = entry.item()  # type: ignore (LazyType)
        _validate_metadata_entry(entry)
    elif LazyType("scipy.sparse", "spmatrix").isinstance(entry):
        raise ValueError(
            "SciPy sparse matrices are currently not supported as metadata items; consider using a dictionary instead"
        )
    elif LazyType("pandas", "Series").isinstance(entry):
        entry = {entry.name: entry.to_dict()}
        _validate_metadata_entry(entry)
    elif LazyType("pandas.api.extensions", "ExtensionArray").isinstance(entry):
        entry = entry.to_numpy().tolist()  # type: ignore (LazyType)
        _validate_metadata_entry(entry)
    elif LazyType("pandas", "DataFrame").isinstance(entry):
        entry = entry.to_dict()  # type: ignore (LazyType)
        validate_metadata(entry)  # type: ignore (LazyType)
    elif LazyType("pandas", "Timestamp").isinstance(entry):
        entry = entry.to_pydatetime()  # type: ignore (LazyType)
    elif LazyType("pandas", "Timedelta").isinstance(entry):
        entry = entry.to_pytimedelta()  # type: ignore (LazyType)
    elif LazyType("pandas", "Period").isinstance(entry):
        entry = entry.to_timestamp().to_pydatetime()  # type: ignore (LazyType)
    elif LazyType("pandas", "Interval").isinstance(entry):
        entry = (entry.left, entry.right)  # type: ignore (LazyType)
        _validate_metadata_entry(entry)
    elif not isinstance(
        entry, (str, bytes, bool, int, float, complex, datetime, date, time, timedelta)
    ):
        raise ValueError(
            f"metadata entries must be basic python types like 'str', 'int', or 'complex', got '{type(entry).__name__}'"
        )

    return entry

def write_to_bento(self, bento_fs: FS, build_ctx: str) -> None:
    if self.is_empty():
        return

    conda_folder = fs.path.join("env", "conda")
    bento_fs.makedirs(conda_folder, recreate=True)

    if self.environment_yml is not None:
        environment_yml_file = resolve_user_filepath(
            self.environment_yml, build_ctx
        )
        copy_file_to_fs_folder(
            environment_yml_file,
            bento_fs,
            conda_folder,
            dst_filename=CONDA_ENV_YAML_FILE_NAME,
        )
    else:
        deps_list: DependencyType = []
        if self.dependencies is not None:
            deps_list.extend(self.dependencies)
        if self.pip is not None:
            if any(isinstance(x, dict) for x in deps_list):
                raise BentoMLException(
                    "Cannot not have both 'conda.dependencies.pip' and 'conda.pip'"
                )
            deps_list.append({"pip": self.pip})

        if not deps_list:
            return

        yaml_content: CondaYamlDict = {"dependencies": deps_list}
        assert self.channels is not None
        yaml_content["channels"] = self.channels
        with bento_fs.open(
            fs.path.combine(conda_folder, CONDA_ENV_YAML_FILE_NAME), "w"
        ) as f:
            yaml.dump(yaml_content, f)

def is_empty(self) -> bool:
    return (
        not self.dependencies
        and not self.pip
        and not self.channels
        and not self.environment_yml
    )

def get_python_version(self, bento_fs: FS) -> str | None:
    # Get the python version from given environment.yml file

    environment_yml = bento_fs.getsyspath(
        fs.path.join(
            "env",
            "conda",
            CONDA_ENV_YAML_FILE_NAME,
        )
    )
    if os.path.exists(environment_yml):
        with open(environment_yml, "r") as f:
            for line in f:
                match = re.search(r"(?:python=)(\d+.\d+)$", line)
                if match:
                    return match.group().split("=")[-1]
        logger.debug(
            "No python version is specified under '%s'. Using the Python options specified under 'docker'.",
            environment_yml,
        )

