def from_item(cls, item: str | dict[str, t.Any] | ModelSpec) -> ModelSpec:
    if isinstance(item, str):
        return cls(tag=item)
    if isinstance(item, ModelSpec):
        return item
    return cls(**item)

def __attrs_post_init__(self) -> None:
    use_conda = not self.conda.is_empty()
    use_cuda = self.docker.cuda_version is not None

    if use_cuda and use_conda:
        logger.warning(
            "BentoML does not support using both conda dependencies and setting a CUDA version for GPU. If you need both conda and CUDA, use a custom base image or create a dockerfile_template, see https://docs.bentoml.com/en/latest/concepts/bento.html#custom-base-image-advanced"
        )

    if self.docker.distro is not None:
        if use_conda and self.docker.distro not in get_supported_spec("miniconda"):
            raise BentoMLException(
                f"{self.docker.distro} does not supports conda. BentoML will only support conda with the following distros: {get_supported_spec('miniconda')}."
            )

        spec = DistroSpec.from_options(self.docker, self.conda)
        if (
            self.docker.python_version is not None
            and self.docker.python_version not in spec.supported_python_versions
        ):
            raise BentoMLException(
                f"{self.docker.python_version} is not supported for {self.docker.distro}. Supported python versions are: {', '.join(spec.supported_python_versions)}."
            )

        if self.docker.cuda_version is not None:
            if spec.supported_cuda_versions is None:
                raise BentoMLException(
                    f"{self.docker.distro} does not support CUDA, while 'docker.cuda_version={self.docker.cuda_version}' is provided."
                )
            if self.docker.cuda_version != "default" and (
                self.docker.cuda_version not in spec.supported_cuda_versions
            ):
                raise BentoMLException(
                    f"{self.docker.cuda_version} is not supported for {self.docker.distro}. Supported cuda versions are: {', '.join(spec.supported_cuda_versions)}."
                )

def from_options(cls, docker: DockerOptions, conda: CondaOptions) -> DistroSpec:
    if not docker.distro:
        raise BentoMLException("Distro is required, got None instead.")

    if docker.distro not in CONTAINER_METADATA:
        raise BentoMLException(
            f"{docker.distro} is not supported. Supported distros are: {', '.join(CONTAINER_METADATA.keys())}."
        )

    if docker.cuda_version is not None:
        release_type = "cuda"
    elif not conda.is_empty():
        release_type = "miniconda"
    else:
        release_type = "python"

    meta = CONTAINER_METADATA[docker.distro]

    return cls(
        **meta[release_type],
        name=docker.distro,
        supported_python_versions=meta["supported_python_versions"],
        supported_cuda_versions=meta["supported_cuda_versions"],
    )

def from_yaml(cls, stream: t.TextIO) -> BentoBuildConfig:
    try:
        yaml_content = yaml.safe_load(stream)
    except yaml.YAMLError as exc:
        logger.error(exc)
        raise

    try:
        return bentoml_cattr.structure(yaml_content, cls)
    except TypeError as e:
        if "missing 1 required positional argument: 'service'" in str(e):
            raise InvalidArgument(
                'Missing required build config field "service", which indicates import path of target bentoml.Service instance. e.g.: "service: fraud_detector.py:svc"'
            ) from e
        else:
            raise InvalidArgument(str(e)) from e

def should_include(self, path: str | Path) -> bool:
    # returns True if file with 'path' has changed, else False
    if isinstance(path, Path):
        path = path.__fspath__()

    return any(
        self.bento_spec.includes(
            path,
            recurse_exclude_spec=filter(
                lambda s: fs.path.isparent(s[0], os.path.dirname(path)),
                self.bento_spec.from_path(dirs),
            ),
        )
        for dirs in self.watch_dirs
    )

def has_modification(self) -> bool:
    for changes in self.file_changes:
        uniq_paths = {Path(c[1]) for c in changes}
        filtered = [c for c in uniq_paths if self.should_include(c)]
        if filtered:
            change_type, path = self.display_path(changes)
            logger.warning("%s: %s", change_type.upper(), path)
            return True
    return False

def display_path(self, change: set[FileChange]) -> tuple[str, str]:
    type_change, path = change.pop()
    try:
        return (
            type_change.raw_str(),
            f"'{Path(path).relative_to(self.working_dir)}'",
        )
    except ValueError:
        return type_change.raw_str(), f"'{path}'"

def __init__(self, **inputs: IODescriptor[t.Any]):
    if any(isinstance(descriptor, Multipart) for descriptor in inputs.values()):
        raise InvalidArgument(
            "Multipart IO can not contain nested Multipart IO descriptor"
        ) from None
    self._inputs = inputs

def from_spec(spec: dict[str, t.Any]) -> IODescriptor[t.Any]:
    if "id" not in spec:
        raise InvalidArgument(f"IO descriptor spec ({spec}) missing ID.")

    if spec["id"] is None:
        raise InvalidArgument("No IO descriptor spec found.")

    return IO_DESCRIPTOR_REGISTRY[spec["id"]].from_spec(spec)

def to_spec(self) -> dict[str, t.Any]:
    return {
        "id": super().descriptor_id,
        "args": {
            "kind": "binaryio",
            "mime_type": self._mime_type,
        },
    }

def _from_sample(self, sample: JSONType) -> JSONType:
    """
    Create a :class:`~bentoml._internal.io_descriptors.json.JSON` IO Descriptor from given inputs.

    Args:
        sample: A JSON-like datatype, which can be either dict, str, list.
                ``sample`` will also accepting a Pydantic model.

                .. code-block:: python

                    from pydantic import BaseModel

                    class IrisFeatures(BaseModel):
                        sepal_len: float
                        sepal_width: float
                        petal_len: float
                        petal_width: float

                    input_spec = JSON.from_sample(
                        IrisFeatures(sepal_len=1.0, sepal_width=2.0, petal_len=3.0, petal_width=4.0)
                    )

                    @svc.api(input=input_spec, output=NumpyNdarray())
                    async def predict(input: NDArray[np.int16]) -> NDArray[Any]:
                        return await runner.async_run(input)
        json_encoder: Optional JSON encoder.

    Returns:
        :class:`~bentoml._internal.io_descriptors.json.JSON`: IODescriptor from given users inputs.

    Example:

    .. code-block:: python
       :caption: `service.py`

       from __future__ import annotations

       import bentoml
       from typing import Any
       from bentoml.io import JSON

       input_spec = JSON.from_sample({"Hello": "World", "foo": "bar"})
       @svc.api(input=input_spec, output=JSON())
       async def predict(input: dict[str, Any]) -> dict[str, Any]:
           return await runner.async_run(input)

    Raises:
        :class:`BadInput`: Given sample is not a valid JSON string, bytes, or supported nest types.
    """
    if LazyType["pydantic.BaseModel"]("pydantic.BaseModel").isinstance(sample):
        self._pydantic_model = sample.__class__
    elif isinstance(sample, str):
        try:
            sample = json.loads(sample)
        except json.JSONDecodeError as e:
            raise BadInput(
                f"Unable to parse JSON string. Please make sure the input is a valid JSON string: {e}"
            ) from None
    elif isinstance(sample, bytes):
        try:
            sample = json.loads(sample.decode())
        except json.JSONDecodeError as e:
            raise BadInput(
                f"Unable to parse JSON bytes. Please make sure the input is a valid JSON bytes: {e}"
            ) from None
    elif not isinstance(sample, (dict, list)):
        raise BadInput(
            f"Unable to infer JSON type from sample: {sample}. Please make sure the input is a valid JSON object."
        )
    return sample

def to_spec(self) -> dict[str, t.Any]:
    return {
