def acquire(self):
    if self.sema < 1:
        return False
    self.sema -= 1
    return True

async def outbound_call(self, inputs_info: tuple[Job, ...]):
    _time_start = time.time()
    _done = False
    batch_size = len(inputs_info)
    logger.debug("Dynamic batching cork released, batch size: %d", batch_size)
    try:
        outputs = await self.callback(
            tuple(t.cast(t.Any, input_info.data) for input_info in inputs_info)
        )
        assert len(outputs) == len(inputs_info)
        for input_info, out in zip(inputs_info, outputs):
            fut = input_info.future
            if not fut.done():
                fut.set_result(out)
        _done = True
        self.optimizer.log_outbound(
            n=len(inputs_info),
            wait=_time_start - inputs_info[-1].enqueue_time,
            duration=time.time() - _time_start,
        )
    except Exception as e:  # pylint: disable=broad-except
        for input_info in inputs_info:
            fut = input_info.future
            if not fut.done():
                fut.set_result(e)
        _done = True
    finally:
        if not _done:
            for input_info in inputs_info:
                fut = input_info.future
                if not fut.done():
                    fut.cancel()
        self._sema.release()

async def _func(data: t.Any) -> t.Any:
    if self._controller is None:
        self._controller = self._loop.create_task(self.controller())
    try:
        r = await self.inbound_call(data)
    except asyncio.CancelledError:
        return None if self.fallback is None else self.fallback()
    if isinstance(r, Exception):
        raise r
    return r

def _validate_name(api_name: str):
    if not api_name.isidentifier():
        raise InvalidArgument(
            "Invalid API name: '{}', a valid identifier may only contain letters,"
            " numbers, underscores and not starting with a number.".format(api_name)
        )

    if api_name in RESERVED_API_NAMES:
        raise InvalidArgument(
            "Reserved API name: '{}' is reserved for infra endpoints".format(
                api_name
            )
        )

def _validate_route(route: str):
    if re.findall(
        r"[?#]+|^(//)|^:", route
    ):  # contains '?' or '#' OR  start with '//' OR start with ':'
        # https://tools.ietf.org/html/rfc3986#page-22
        raise InvalidArgument(
            "The path {} contains illegal url characters".format(route)
        )
    if route in RESERVED_API_NAMES:
        raise InvalidArgument(
            "Reserved API route: '{}' is reserved for infra endpoints".format(route)
        )

