    if not self.email:
        cli = self.get_rest_api_client()
        user = cli.get_current_user()
        if user is None:
            raise CloudRESTApiClientError(
                "Unable to get current user from yatai server"
            )
        self.email = user.email
        add_context(self, ignore_warning=True)
    return self.email

